//! Disposable test harness: stdin/stdout JSON, not an application network endpoint.
use delta_host_runtime::HostRuntime;use serde_json::{json,Value};use std::io::{BufRead,Write};
#[tokio::main]async fn main(){let home=std::env::var_os("DELTA_TEST_HOME").expect("Disposable DELTA_TEST_HOME required");let runtime=HostRuntime::open(home.into(),"desktop").await.unwrap();for line in std::io::stdin().lock().lines(){let Ok(line)=line else{break};let Ok(v)=serde_json::from_str::<Value>(&line)else{continue};let result=if v["capability"]=="host.info"{Ok(runtime.info("0.1.1","0.1.3"))}else{{let mut r=v.clone();r.as_object_mut().unwrap().remove("id");runtime.call(r).await}};let envelope=match result{Ok(result)=>json!({"ok":true,"result":result}),Err(e)=>json!({"ok":false,"error":e.to_value()})};println!("{}",json!({"id":v["id"],"envelope":envelope}));std::io::stdout().flush().unwrap();}runtime.stop().await;}
